/* Inventory review UI replacement. Original stock records stay untouched. */
(function(){'use strict';
var root=document.getElementById('inventory');if(!root||root.dataset.rebuiltInventory)return;
root.dataset.rebuiltInventory='yes';
var escapeHtml=function(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});};
var f=function(v){return (Number(v)||0).toLocaleString('ko-KR',{minimumFractionDigits:3,maximumFractionDigits:3});};
var categories={RM:'원자재',PM:'부자재',WIP:'중간배치',FG:'완제품'};
var states={AVAILABLE:'사용가능',IQC_PENDING:'IQC 대기',OQC_PENDING:'OQC 대기',HOLD:'보류',NONCONFORM:'부적합',RESERVED:'예약'};
var data=[],transactions=[],view=[],page=1;
root.innerHTML='<div class="namo-new-stock"><header><div><h1>재고현황</h1><p>LOT별 원자재 · 중간배치 · 완제품 재고</p></div><div><button id="stockReload">새로고침</button><button id="stockCsv">엑셀</button><button id="stockPrint">인쇄</button></div></header><p class="stockMessage" id="stockMessage">운영 재고 조회 중입니다.</p><div class="stockCards" id="stockCards"></div><section class="stockFilters"><label>재고 구분 <select id="stockCat"><option value="">전체</option>'+Object.keys(categories).map(function(k){return '<option value="'+k+'">'+categories[k]+'</option>';}).join('')+'</select></label><label>품질상태 <select id="stockStatus"><option value="">전체</option>'+Object.keys(states).map(function(k){return '<option value="'+k+'">'+states[k]+'</option>';}).join('')+'</select></label><label>품목·LOT 검색 <input id="stockSearch" placeholder="품목코드·품목명·LOT NO"></label><button id="stockClear">초기화</button></section><h3>LOT별 재고 조회 <span id="stockCount"></span></h3><div class="stockTable"><table><thead><tr><th>No.</th><th>구분</th><th>품목코드</th><th>품목명</th><th>LOT NO</th><th>장부 현재고(kg)</th><th>가용재고(kg)</th><th>상태</th><th>보관위치</th><th>비고</th></tr></thead><tbody id="stockRows"></tbody></table></div><nav id="stockPager"></nav><footer><strong>검증 기준</strong><p>원자재: 수입검사 입고 − 실제 생산 투입 ± 조정 / 완제품: 생산 완료 − 실제 출하 ± 조정</p><p>현재 원장 잔량과 최근 거래이력을 표시하며, 생산·출하 기록 전수 대조 전에는 정확한 재고로 확정하지 않습니다. 이 화면은 DB 재고를 수정하거나 삭제하지 않습니다.</p></footer></div><dialog id="stockDialog"><h3>LOT 입출고 이력</h3><div id="stockDetail"></div><button id="stockClose">닫기</button></dialog>';
var node=function(id){return root.querySelector('#'+id);};
var duplicate=function(r){return String(r.lot_no).toUpperCase()==='HIST-20260521-DBE2001'&&data.some(function(x){return x.item_code===r.item_code&&String(x.lot_no).toUpperCase()==='DBE2001';});};
var sum=function(rows){return rows.reduce(function(a,r){return a+(Number(r.quantity)||0);},0);};
function filter(){var cat=node('stockCat').value,status=node('stockStatus').value,query=node('stockSearch').value.toLowerCase().trim();
view=data.filter(function(r){return (!cat||r.category===cat)&&(!status||r.quality_status===status)&&(!query||[r.item_code,r.item_name,r.lot_no].join(' ').toLowerCase().includes(query));});page=1;draw();}
function draw(){var total=sum(view),dups=view.filter(duplicate),dupTotal=sum(dups),available=view.filter(function(r){return !duplicate(r)&&r.quality_status==='AVAILABLE';}).reduce(function(a,r){return a+(Number(r.available_qty)||0);},0);
node('stockCards').innerHTML=[['장부 현재고',f(total)+' kg'],['중복 확인',f(dupTotal)+' kg'],['중복 제외 검토값',f(total-dupTotal)+' kg'],['사용가능 재고',f(available)+' kg']].map(function(v){return '<div class="stockCard"><small>'+v[0]+'</small><strong>'+v[1]+'</strong></div>';}).join('');
node('stockMessage').textContent=dupTotal?'확인된 중복 LOT '+dups.length+'건을 검토값에서만 제외했습니다. 원본 DB와 거래이력은 유지합니다.':'운영 재고 원장 조회값입니다. 생산·출하 전수 대조 전까지 정확성은 미확정입니다.';
node('stockCount').textContent='('+view.length+'건)';
node('stockRows').innerHTML=view.slice((page-1)*10,page*10).map(function(r,i){return '<tr'+(duplicate(r)?' class="stockDuplicate"':'')+'><td>'+((page-1)*10+i+1)+'</td><td>'+escapeHtml(categories[r.category]||r.category)+'</td><td>'+escapeHtml(r.item_code)+'</td><td>'+escapeHtml(r.item_name)+'</td><td><button class="stockLot" data-index="'+data.indexOf(r)+'">'+escapeHtml(r.lot_no)+'</button></td><td>'+f(r.quantity)+'</td><td>'+f(!duplicate(r)&&r.quality_status==='AVAILABLE'?r.available_qty:0)+'</td><td>'+escapeHtml(duplicate(r)?'중복 확인':states[r.quality_status]||r.quality_status)+'</td><td>'+escapeHtml(r.location_code)+'</td><td><button data-index="'+data.indexOf(r)+'">상세</button></td></tr>';}).join('')||'<tr><td colspan="10">조회 결과가 없습니다.</td></tr>';
var max=Math.max(1,Math.ceil(view.length/10));node('stockPager').innerHTML='<button id="stockPrev" '+(page===1?'disabled':'')+'>이전</button> '+page+' / '+max+' <button id="stockNext" '+(page===max?'disabled':'')+'>다음</button>';
node('stockPrev').onclick=function(){page--;draw();};node('stockNext').onclick=function(){page++;draw();};}
async function query(path){var resp=await fetch(path,{credentials:'same-origin',cache:'no-store'}),obj=await resp.json();if(!resp.ok||obj.success===false)throw Error(obj.message||'조회 실패');return obj.data||obj;}
async function load(){node('stockMessage').textContent='운영 재고 조회 중...';try{var result=await Promise.all([query('/api/inventory/stock'),query('/api/inventory/transactions?limit=1000')]);if(!Array.isArray(result[0])||!Array.isArray(result[1]))throw Error('응답 형식 오류');data=result[0];transactions=result[1];filter();}catch(e){node('stockMessage').textContent='재고 조회 실패: '+e.message;node('stockRows').innerHTML='<tr><td colspan="10">데이터를 불러오지 못했습니다. 원본은 변경되지 않았습니다.</td></tr>';}}
node('stockRows').onclick=function(e){var b=e.target.closest('[data-index]');if(!b)return;var r=data[Number(b.dataset.index)],rows=transactions.filter(function(t){return t.item_code===r.item_code&&t.lot_no===r.lot_no;});node('stockDetail').innerHTML='<p><strong>'+escapeHtml(r.item_code)+' / '+escapeHtml(r.lot_no)+'</strong> · '+f(r.quantity)+'kg</p><p>아래 내역은 최근 전체 거래 최대 1,000건 내에서만 조회됩니다.</p><div class="stockTable"><table><thead><tr><th>일시</th><th>거래</th><th>수량(kg)</th><th>작업지시번호</th><th>참조번호</th></tr></thead><tbody>'+rows.map(function(t){return '<tr><td>'+escapeHtml(String(t.created_at).slice(0,19))+'</td><td>'+escapeHtml(t.transaction_type)+'</td><td>'+f(t.quantity)+'</td><td>'+escapeHtml(t.work_order_no)+'</td><td>'+escapeHtml(t.reference_no)+'</td></tr>';}).join('')+'</tbody></table></div>';node('stockDialog').showModal();};
node('stockClose').onclick=function(){node('stockDialog').close();};
node('stockReload').onclick=load;node('stockCat').onchange=filter;node('stockStatus').onchange=filter;node('stockSearch').oninput=filter;node('stockClear').onclick=function(){node('stockCat').value='';node('stockStatus').value='';node('stockSearch').value='';filter();};
node('stockPrint').onclick=function(){window.print();};
node('stockCsv').onclick=function(){var lines=[['구분','품목코드','품목명','LOT NO','장부 현재고','가용재고','상태','위치','중복 여부']].concat(view.map(function(r){return [categories[r.category]||r.category,r.item_code,r.item_name,r.lot_no,r.quantity,duplicate(r)?0:(r.available_qty||0),states[r.quality_status]||r.quality_status,r.location_code,duplicate(r)?'중복':''];}));var out='\uFEFF'+lines.map(function(cols){return cols.map(function(x){return '"'+String(x==null?'':x).replace(/"/g,'""')+'"';}).join(',');}).join('\r\n');var url=URL.createObjectURL(new Blob([out],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='QMES_재고현황_검토용.csv';a.click();setTimeout(function(){URL.revokeObjectURL(url);},1500);};
var style=document.createElement('style');style.textContent='#inventory .namo-new-stock{background:#fff;border:1px solid #dce5ee;border-radius:10px;color:#243d59;overflow:hidden}#inventory .namo-new-stock header{padding:20px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #dae4ee}#inventory .namo-new-stock h1{font-size:22px;color:#183c61;margin:0}#inventory .namo-new-stock header p{font-size:12px;color:#6b7c90}#inventory .namo-new-stock button{cursor:pointer;background:#fff;border:1px solid #cad8e6;border-radius:5px;color:#23496d;padding:7px 12px;margin:2px}#inventory .stockMessage{padding:12px 20px;background:#f4f8fb;font-size:12px}#inventory .stockCards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;padding:15px 20px}#inventory .stockCard{background:#f4f8fc;border:1px solid #e1eaf3;border-radius:7px;padding:14px}#inventory .stockCard small{display:block;color:#678;margin-bottom:8px}#inventory .stockCard strong{font-size:18px}#inventory .stockFilters{display:flex;align-items:end;gap:12px;flex-wrap:wrap;background:#f3f7fc;padding:15px 20px}#inventory .stockFilters label{display:flex;flex-direction:column;font-size:12px;gap:5px}#inventory .stockFilters input,#inventory .stockFilters select{height:34px;background:#fff;border:1px solid #cbd6e3;border-radius:4px;padding:5px}#inventory .namo-new-stock h3{padding:10px 20px}#inventory .stockTable{overflow:auto}#inventory .stockTable table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:12px}#inventory .stockTable th{background:#ecf3fa;color:#355875}#inventory .stockTable td,#inventory .stockTable th{padding:11px;border-bottom:1px solid #e1e9f1;text-align:center}#inventory .stockLot{color:#0b65b5!important;text-decoration:underline}#inventory .stockDuplicate{background:#fff1ed}#inventory #stockPager{text-align:center;padding:14px}#inventory .namo-new-stock footer{padding:14px 20px;background:#f7f9fc;font-size:12px}#inventory #stockDialog{max-width:90vw;max-height:80vh;border:1px solid #cbd6e3;border-radius:8px;padding:24px}@media(max-width:800px){#inventory .stockCards{grid-template-columns:repeat(2,1fr)}}';document.head.append(style);
load();
})();